import { WHOLE, type Mix } from "@/stitch/mix";

// The world that tells every chapter: the agent chooses it to suit the
// person, from the library's gallery. WHOLE.sheet, WHOLE.map or WHOLE.book;
// as one line "map,map,map,map,map,map,map,map" (parseMix and formatMix in
// stitch/mix.ts), which is also what /preview?mix= takes.
export const mix: Mix = WHOLE.sheet;
// The looks a stitched story can wear: the colours every world draws with,
// and the colours of the words over it. A look colours the ground, paper,
// ink and accent; a world's own materials (the book's desk and page tints)
// stay the same in every look. Pure.

/** `amber` is the accent in every look, whatever its hue. */
export type Palette = {
  bg: string; paper: string; paperDark: string; card: string; ink: string; muted: string;
  amber: string; teal: string; rose: string; blue: string; line: string;
};
export type LookId = "night" | "daylight" | "blueprint";
export const LOOK_IDS: readonly LookId[] = ["night", "daylight", "blueprint"];

export const LOOKS: Record<LookId, Palette> = {
  night: {
    bg: "#0f1318", paper: "#f2ede2", paperDark: "#e3dccd", card: "#fbf7ee", ink: "#1c222a", muted: "#6d7782",
    amber: "#e9a23b", teal: "#3fa796", rose: "#d8665a", blue: "#4c7fd1", line: "#c9c1b0",
  },
  daylight: {
    bg: "#e7e3da", paper: "#fbf8f2", paperDark: "#ebe5d8", card: "#ffffff", ink: "#1c222a", muted: "#5f6872",
    amber: "#c9741f", teal: "#2f8a7b", rose: "#c4513f", blue: "#3d6fc0", line: "#cfc6b4",
  },
  blueprint: {
    bg: "#0e2236", paper: "#eaf0f5", paperDark: "#d5dfe8", card: "#f6f9fb", ink: "#13202c", muted: "#5a6875",
    amber: "#f2b33d", teal: "#48b3a6", rose: "#e27b6b", blue: "#6a9be0", line: "#b9c6d2",
  },
};

export const parseLook = (text: string | null | undefined): LookId | null =>
  (LOOK_IDS as readonly string[]).includes(String(text)) ? (text as LookId) : null;

const rgb = (hex: string): [number, number, number] => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16)) as [number, number, number];
const hex2 = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");

/** WCAG relative luminance of #rrggbb. */
export function luminance(hex: string): number {
  const [r, g, b] = rgb(hex).map((v) => { const c = v / 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** The WCAG contrast ratio of two #rrggbb colours, 1 to 21. */
export function contrast(a: string, b: string): number {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

/** Whether a look's ground is dark, so the words over it are light. */
export const isDark = (p: Palette): boolean => luminance(p.bg) < 0.2;

/** A #rrggbb colour with a transparency, as CSS and canvas take it. */
export const rgba = (hex: string, a: number): string => `rgba(${rgb(hex).join(",")},${a})`;

/** A colour moved by a fixed amount on each channel. */
const shift = (hex: string, d: [number, number, number]) => `#${rgb(hex).map((v, i) => hex2(v + d[i])).join("")}`;

/** The ground behind the worlds: the backdrop's centre, middle and edge, the map's ground, its grid and its land dots. */
export function groundTones(p: Palette): { centre: string; middle: string; edge: string; map: string; grid: string; land: string } {
  const dark = isDark(p);
  return {
    centre: shift(p.bg, [14, 18, 22]),
    middle: shift(p.bg, [1, 2, 3]),
    edge: shift(p.bg, [-5, -6, -7]),
    map: shift(p.bg, [6, 9, 11]),
    grid: dark ? "rgba(255,255,255,0.05)" : "rgba(28,34,42,0.07)",
    land: dark ? "rgba(150,178,186,0.55)" : "rgba(80,96,104,0.45)",
  };
}

/** The colours of the words, rail, caption glass and buttons over a look's ground. */
export function uiColours(p: Palette): { text: string; soft: string; muted: string; glass: string; line: string; onText: string } {
  return isDark(p)
    ? { text: "#ece6d9", soft: "#c9cfd5", muted: "#9aa4ae", glass: "rgba(12, 16, 21, 0.72)", line: "rgba(236, 230, 217, 0.14)", onText: "#11161c" }
    : { text: p.ink, soft: "#2c333b", muted: "#5a636d", glass: "rgba(255, 255, 255, 0.8)", line: "rgba(28, 34, 42, 0.14)", onText: "#f2ede2" };
}

  return (
    <div className={`stitch${showWords ? "" : " nowords"}${keys.every((k) => mix[k] === "book") ? " allbook" : ""}`} data-scene={scene} style={lookStyle(palette)}>
      <div className="frame">
        {topbar && (
          <header className="topbar">
            {chapterLink("hello", person.name, "brand")}
            <nav aria-label="Main">
              {keys.includes("made") && chapterLink("made", "Work")}
              {chapterLink("contact", "Contact")}
              {cv && <a href={cv}>CV</a>}
            </nav>
          </header>
        )}
        <div className="view">
          <canvas ref={canvasRef} className="gl" aria-hidden="true" />
          <nav className="rail" aria-label="Chapters">
            {keys.map((k, i) => (
              <button key={k} type="button" className={i === near ? "on" : ""} onClick={() => handle.current?.goTo(i)}>
                <i /><span>{titleOf(k)}</span>
              </button>
            ))}
          </nav>
          <div ref={hintRef} className="hint">Scroll</div>
        </div>
        {/* Every chapter's caption in one place, so the band is as tall as the tallest and the view never changes size. */}
        <div ref={bandRef} className="band" aria-live="polite">
          {keys.map((k, i) => (
            <div key={k} className={`cap${i === near ? " on" : ""}${mix[k] === "book" ? " inbook" : ""}`} aria-hidden={i !== near}>
              <div className="words">
                <div className="num">{String(i + 1).padStart(2, "0")}</div>
                <h2>{titleOf(k)}</h2>
                <p>{words[k]}</p>
              </div>
              {k === "made" && (
                <div className="links" aria-label="Open a project">
                  {person.projects.map((p) => <button key={p.title} type="button" onClick={() => setProject(p)}>{p.title}</button>)}
                </div>
              )}
              {k === "contact" && (
                <div className="links actions">
                  <a href={`mailto:${person.contact.email}`}>Email {person.first}</a>
                  {cv && <a href={cv}>CV</a>}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
      <div ref={spacerRef} className="spacer" />
      <Chapters person={person} keys={keys} words={words} cv={cv} />
      <Expected person={person} words={words} cv={cv} />
      {project && <ProjectWindow project={project} palette={palette} onClose={() => setProject(null)} />}
    </div>
  );
}

/** Every chapter's words in order, shown when there is no 3D and read by screen readers. */
function Chapters({ person, keys, words, cv }: { person: Person; keys: ChapterKey[]; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  return (
    <section className="text" aria-label={`${person.name}, in words`}>
      <h1>{person.name}</h1>
      {keys.map((k) => (
        <article key={k} id={k}>
          <h2>{titleOf(k)}</h2>
          <p>{words[k]}</p>
          {k === "made" && <ul>{person.projects.map((p) => <li key={p.title}><b>{p.page ? <a href={p.page}>{p.title}</a> : p.title}</b>. {p.line}{p.more && <> {p.more}</>}</li>)}</ul>}
          {k === "say" && <ul>{person.quotes.map((q) => <li key={q.who}>&ldquo;{q.text}&rdquo; {q.who}, {q.from}</li>)}</ul>}
          {k === "contact" && <p><a href={`mailto:${person.contact.email}`}>{person.contact.email}</a>{cv && <>. <a href={cv}>CV</a></>}</p>}
        </article>
      ))}
    </section>
  );
}

/** What the page must show without its 3D, as JSON for scripts/site-check.mjs to look for. */
function Expected({ person, words, cv }: { person: Person; words: Partial<Record<ChapterKey, string>>; cv?: string }) {
  const wanted = {
    name: person.name,
    words: Object.values(words),
    projects: person.projects.map(({ title, line, more, page }) => ({ title, line, more, page })),
    cv,
  };
  return <script type="application/json" data-stitch-expect dangerouslySetInnerHTML={{ __html: JSON.stringify(wanted).replace(/</g, "\\u003c") }} />;
}

/** A native dialog: the page behind it cannot be reached, Escape closes it, and focus goes back where it was. */
function ProjectWindow({ project, palette, onClose }: { project: Project; palette: Palette; onClose: () => void }) {
  const pic = useRef<HTMLDivElement>(null);
  const box = useRef<HTMLDialogElement>(null);
  // The project at work: its picture plays through what it does, then rests on the result. Reduced motion shows the result.
  useEffect(() => {
    const el = pic.current;
    if (!el) return;
    const draw = (run: number) => (ctx: CanvasRenderingContext2D, w: number, h: number) => {
      ctx.clearRect(0, 0, w, h);
      miniPicture(ctx, palette, project.kind, 0, 0, w, h, project.title.length, run);
    };
    const c = paintCanvas(800, 420, draw(1));
    el.replaceChildren(c);
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const ctx = c.getContext("2d")!, start = performance.now();
    let raf = 0;
    const frame = (now: number) => {
      const t = ((now - start) / 1000) % 5; // four seconds of work, one at rest
      draw(Math.min(1, t / 4))(ctx, c.width, c.height);
      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [project, palette]);
  useEffect(() => {
    const d = box.current;
    if (!d) return;
    const back = document.activeElement as HTMLElement | null;
    d.showModal();
    return () => { d.close(); back?.focus({ preventScroll: true }); };
  }, []);
  return (
    <dialog ref={box} className="modal" aria-label={project.title}
      onClose={onClose} onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="sheet">
        <button type="button" data-close aria-label="Close" onClick={onClose}>&times;</button>
        <div className="pic" ref={pic} aria-hidden="true" />
        <div className="body">
          <div className="eyebrow">{project.place}, {project.year}</div>
          <h3>{project.title}</h3>
          <p>{project.line}</p>
          {project.more && <p>{project.more}</p>}
          {project.page && <p><a className="more" href={project.page}>More about {project.title}</a></p>}
          <div className="tags">{project.tags.map((t) => <span key={t}>{t}</span>)}</div>
        </div>
      </div>
    </dialog>
  );
}
